const webhook = $('Webhook – From Flow #3 (Scoring)')?.first()?.json || {};

const incoming = webhook.body || webhook;

const profileItems = $input.all();
const profile = (profileItems?.[0]?.json?.phone) ? profileItems[0].json : {};

const phone = incoming.phone || incoming.lead_phone || profile.phone || profile.lead_phone || '';
const name = incoming.name || incoming.lead_name || incoming.full_name || profile.name || profile.lead_name || 'عميل جديد';
const email = incoming.email || incoming.lead_email || profile.email || '';
const source = incoming.source || profile.source || 'unknown';

const final_score = incoming.score || incoming.final_score || profile.final_score || profile.score || 0;
const status = incoming.status || incoming.lead_status || profile.status || 'New';
const lead_category = incoming.category || incoming.lead_category || profile.category || profile.lead_category || 'B2C_solo';

const radar_intent = incoming.radar_intent || profile.radar_intent || 'general_inquiry';
const radar_urgency = incoming.radar_urgency || profile.radar_urgency || 'normal';
const budget_signal = incoming.budget_signal || profile.budget_signal || 'unknown';
const order_type = incoming.order_type || profile.order_type || 'unknown';
const service_preference = incoming.service_preference || profile.service_preference || 'any';

const phones_found = incoming.phones_found || profile.phones_found || (phone ? [phone] : []);
const quantity_hint = incoming.quantity || incoming.quantity_hint || profile.quantity || profile.quantity_hint || 0;

const storedStep = profile.journey_step || 'new';
const isHot = status === 'Hot' || final_score >= 85;
const isB2B = lead_category.toUpperCase().startsWith('B2B');
const isFamily = lead_category.toLowerCase().includes('family') || order_type === 'family';

let journey_step;
if (isHot) {
  journey_step = 'hot_contacted';
} else if (isB2B) {
  journey_step = 'b2b_nurturing';
} else if (status === 'Warm' && final_score >= 60) {
  journey_step = 'warm_followup';
} else if (status === 'Cold' || final_score < 40) {
  journey_step = 'cold_archive';
} else {
  journey_step = storedStep !== 'new' ? storedStep : 'new_lead';
}

const preferred_channel = incoming.preferred_channel || profile.preferred_channel || 
  (phone ? 'whatsapp' : email ? 'email' : 'telegram');

const lastContact = profile.last_contacted_at ? new Date(profile.last_contacted_at) : null;
const now = new Date();
const hours_since_last = lastContact ? Math.round((now - lastContact) / 36e5) : 999;
const tooSoon = hours_since_last < 24 && status !== 'Hot';

const recommended_action = incoming.recommended_action || 
  (isHot ? 'immediate_call' : 
   status === 'Warm' ? 'whatsapp_followup_24h' : 
   'email_nurture');

return [{
  json: {
    phone,
    name,
    email,
    source,

    final_score: Number(final_score),
    status,
    lead_category,

    radar_intent,
    radar_urgency,
    budget_signal,
    order_type,
    service_preference,

    quantity_hint: Number(quantity_hint),
    phones_found: Array.isArray(phones_found) ? phones_found : [phones_found].filter(Boolean),
    preferred_channel,

    journey_step,
    recommended_action,

    tooSoon,
    hours_since_last,
    now_iso: now.toISOString(),

    _debug: {
      incoming_keys: Object.keys(incoming),
      profile_keys: Object.keys(profile),
      score_used: final_score,
      category_used: lead_category,
      using_body_wrapper: !!(webhook.body)
    }
  }
}];

