    const cat = $json.lead_category || '';
    return `${stepEmoji[step]||'📩'} *Journey Message Sent*\n\n` +
      `👤 ${$json.name} | 📞 ${$json.phone}\n` +
      `${chanEmoji[$json.preferred_channel]||'📨'} Channel: ${$json.preferred_channel}\n` +
      `🗺️ Step: ${step} → ${$json.next_journey_step}\n` +
      `📂 Category: ${cat}\n` +
      `📊 Score: ${$json.final_score}/100\n\n` +
      `💬 _${($json.text||'').substring(0,120)}_`;
  })()
}}

